Source code in <code>rdm/kernel/events.py</code> <pre><code>@dataclass(frozen=True)
class Event:
    name: str
    message: str

    @property
    def rule(self) -&gt; str:
        """The business rule a fail event or a warning names: after the slash."""
        return self.name.partition(" / ")[2]

    @property
    def warning(self) -&gt; bool:
        return " Warned / " in self.name

    @property
    def blocking(self) -&gt; bool:
        return " / " in self.name and not self.warning
